SELECT cs.canonical_smiles, met.substrate_record_id, met.metabolite_record_id, cr_sub.compound_key AS substrate_compound_key, cr_met.compound_key AS metabolite_compound_key, met.met_conversion, met.pathway_key FROM metabolism met INNER JOIN compound_records cr_sub ON met.substrate_record_id = cr_sub.record_id INNER JOIN compound_structures cs ON cr_sub.molregno = cs.molregno LEFT JOIN compound_records cr_met ON met.metabolite_record_id = cr_met.record_id LIMIT 200
